size_t group = 0;
size_t bit_offset = 0;
bitmap_t mask;
bitmap_t old_val, new_val;

// Iterate through each group in the bitmap
while (group < binfo->levels[0]) {
    // Load the current group value atomically
    old_val = bitmap[group];
    // If group is not full, find first unset bit
    if (old_val != ~(bitmap_t)0) {
        // Use ffs_lu to find first unset bit (by inverting)
        mask = ~(old_val);
        // ffs_lu returns 0-based index of first set bit in mask
        bit_offset = ffs_lu(mask);
        // Construct the new value by setting the found bit
        new_val = old_val | (static_cast<bitmap_t>(1) << bit_offset);
        // Attempt atomic compare-and-swap
        if (__atomic_compare_exchange_n(&bitmap[group], &old_val, new_val, false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
            // Successfully set the bit, return the global bit index
            return group * BITMAP_GROUP_NBITS + bit_offset;
        }
        // If CAS failed, retry the same group (loop continues)
    }
    group++;
}

// If we reach here, the bitmap is full
return BITMAP_MAXBITS; // Indicate failure by returning max possible bit index

